13	/**
14	 * Server-sent events endpoint. Clients subscribe by passing ?channel=<name>.
15	 * Emits an "update" event whenever the corresponding channel is published to
16	 * via emit() in a server action or service. The client should call
17	 * router.refresh() on receipt to re-render server components with fresh data.
18	 */
19	export function GET(request: NextRequest): Response {
20	    const channel = request.nextUrl.searchParams.get(
21	        'channel',
22	    ) as FootyChannel | null;
23	
24	    if (!channel) {
25	        return new Response('Missing channel parameter', { status: 400 });
26	    }
27	
28	    const stream = new ReadableStream({
29	        start(controller) {
30	            let closed = false;
31	
32	            const listener = () => {
33	                if (closed || request.signal.aborted) return;
34	                try {
35	                    controller.enqueue(
36	                        encoder.encode('event: update\ndata: {}\n\n'),
37	                    );
38	                } catch {
39	                    // Client disconnected between the abort and this write;
40	                    // nothing to send to.
41	                }
42	            };
43	
44	            emitter.on(channel, listener);
45	
46	            request.signal.addEventListener('abort', () => {
47	                closed = true;
48	                emitter.off(channel, listener);
49	                controller.close();
50	            });
51	        },
52	    });
53	
54	    return new Response(stream, {
55	        headers: {
56	            'Content-Type': 'text/event-stream',
57	            'Cache-Control': 'no-cache',
58	            Connection: 'keep-alive',
59	        },
60	    });
61	}
